	function validUid(uid) {
		const value = String(uid);
		if (!/^[1-9]\d*$/.test(value) || !Number.isSafeInteger(Number(value))) {
			throw new Error('[[error:invalid-uid]]');
		}
		return value;
	}

	function isProfileImageFilename(uid, type, filename) {
		const extensions = [...new Set([...User.getAllowedProfileImageExtensions(), 'png', 'jpeg', 'jpg', 'bmp'])]
			.filter(ext => /^[a-z0-9]+$/i.test(ext));
		const pattern = new RegExp(`^${validUid(uid)}-profile${type}(?:-\\d+)?\\.(?:${extensions.join('|')})$`, 'i');
		return pattern.test(filename);
	}

	function getLocalProfileImagePath(url) {
		if (typeof url !== 'string') {
			return false;
		}
		const relativePath = nconf.get('relative_path') || '';
		const uploadUrl = '/assets/uploads/profile/';
		if (relativePath && url.startsWith(uploadUrl)) {
			url = relativePath + url;
		}
		const prefix = relativePath + uploadUrl;
		if (!url.startsWith(prefix)) {
			return false;
		}
		const filename = url.slice(prefix.length);
		if (!filename || filename === '.' || filename === '..' || filename.includes('/') || filename.includes('\\')) {
			return false;
		}
		return path.resolve(nconf.get('upload_path'), 'profile', filename);
	}

	async function getLocalImagePaths(uid, type) {
		uid = validUid(uid);
		const folder = path.resolve(nconf.get('upload_path'), 'profile');
		let filenames;
		try {
			filenames = await fs.promises.readdir(folder);
		} catch (err) {
			if (err.code === 'ENOENT') {
				return [];
			}
			throw err;
		}
		return filenames.filter(filename => isProfileImageFilename(uid, type, filename))
			.map(filename => getLocalProfileImagePath(`${nconf.get('relative_path') || ''}/assets/uploads/profile/${filename}`))
			.filter(Boolean).sort();
	}

	async function deleteLocalFiles(paths) {
		await Promise.all([...new Set(paths)].map(async (localPath) => {
			try {
				await fs.promises.unlink(localPath);
			} catch (err) {
				if (err.code !== 'ENOENT') {
					throw err;
				}
			}
		}));
	}

