		}
		await Groups.setGroupField(groupName, 'cover:position', position);
	};

	Groups.updateCover = async function (uid, data) {
		let tempPath = data.file ? data.file.path : '';
		try {
			// Position only? That's fine
			if (!data.imageData && !data.file && data.position) {
				return await Groups.updateCoverPosition(data.groupName, data.position);
			}
			const type = data.file ? data.file.type : image.mimeFromBase64(data.imageData);
			if (!type || !allowedTypes.includes(type)) {
				throw new Error('[[error:invalid-image]]');
			}

			if (!tempPath) {
				tempPath = await image.writeImageDataToTempFile(data.imageData);
			}

			const oldCover = await db.getObjectFields(`group:${data.groupName}`, ['cover:url', 'cover:thumb:url']);
			const filename = `groupCover-${data.groupName}${path.extname(tempPath)}`;
			const uploadData = await image.uploadImage(filename, 'files', {
				path: tempPath,
				uid: uid,
				name: 'groupCover',
			});
			const { url } = uploadData;
			await Groups.setGroupField(data.groupName, 'cover:url', url);

			await image.resizeImage({
				path: tempPath,
				width: 358,
			});
			const thumbUploadData = await image.uploadImage(`groupCoverThumb-${data.groupName}${path.extname(tempPath)}`, 'files', {
				path: tempPath,
				uid: uid,
				name: 'groupCover',
			});
			await Groups.setGroupField(data.groupName, 'cover:thumb:url', thumbUploadData.url);
			const currentPaths = new Set([url, thumbUploadData.url].map(getLocalCoverPath).filter(Boolean));
			await deleteLocalFiles([oldCover['cover:url'], oldCover['cover:thumb:url']]
				.map(getLocalCoverPath).filter(oldPath => oldPath && !currentPaths.has(oldPath)));

			if (data.position) {
				await Groups.updateCoverPosition(data.groupName, data.position);
			}

			return { url: url };
		} finally {
			file.delete(tempPath);
		}
	};

	Groups.removeCover = async function (data) {
		const cover = await db.getObjectFields(`group:${data.groupName}`, ['cover:url', 'cover:thumb:url']);
		await deleteLocalFiles([cover['cover:url'], cover['cover:thumb:url']].map(getLocalCoverPath).filter(Boolean));
		await db.deleteObjectFields(`group:${data.groupName}`, ['cover:url', 'cover:thumb:url', 'cover:position']);
	};

	function getLocalCoverPath(url) {
		if (typeof url !== 'string') {
			return false;
		}
		const relativePath = nconf.get('relative_path') || '';
		const uploadUrl = '/assets/uploads/files/';
		if (relativePath && url.startsWith(uploadUrl)) {
			url = relativePath + url;
		}
		const prefix = relativePath + uploadUrl;
		if (!url.startsWith(prefix)) {
			return false;
		}
		const filename = url.slice(prefix.length);
		if (!filename || filename === '.' || filename === '..' || filename.includes('/') || filename.includes('\\')) {
			return false;
		}
		const folder = path.resolve(nconf.get('upload_path'), 'files');
		return path.resolve(folder, filename);
	}

	async function deleteLocalFiles(paths) {
		await Promise.all([...new Set(paths)].map(async (localPath) => {
			try {
				await fs.promises.unlink(localPath);
			} catch (err) {
				if (err.code !== 'ENOENT') {
					throw err;
				}
			}
		}));
	}
